SELECT j.id, j.company_id, j.category_id, j.title, j.city, j.district, j.salary_min, j.salary_max, j.education, j.experience, j.description, j.duties, j.requirements, j.skill_tags, j.perks, j.status, j.audit_status, j.audit_reason, j.view_count, j.publish_time, j.create_time, j.update_time, j.deleted FROM job j JOIN company c ON c.id = j.company_id AND c.deleted = 0
j.deleted = 0 AND j.status = 'PUBLISHED' AND j.audit_status = 'APPROVED'
AND (j.title LIKE CONCAT('%', #{keyword}, '%') OR j.city LIKE CONCAT('%', #{keyword}, '%') OR j.skill_tags LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR c.industry LIKE CONCAT('%', #{keyword}, '%'))
AND j.city = #{city}
AND j.salary_max >= #{salaryMin}
AND j.salary_min <= #{salaryMax}
AND j.education = #{education}
AND j.experience = #{experience}
AND (j.category_id = #{categoryId} OR j.category_id IN ( SELECT child.id FROM job_category child WHERE child.parent_id = #{categoryId} AND child.deleted = 0 ))
AND c.industry = #{industry}
ORDER BY j.salary_max DESC ORDER BY j.view_count DESC ORDER BY j.update_time DESC

SELECT FROM job
deleted = 0
AND title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{status}
AND audit_status = #{auditStatus}
ORDER BY update_time DESC
